import React from 'react';

const Settings = ({ onBack, settings, onUpdate }) => {
  const sections = [
    {
      title: "Experiência",
      options: [
        { id: 'darkMode', label: 'Modo Noturno Extremo', type: 'toggle', desc: 'Pretos mais profundos para poupar bateria e olhos.' },
        { id: 'animations', label: 'Animações Fluídas', type: 'toggle', desc: 'Transições suaves entre cartas e menus.' },
      ]
    },
    {
      title: "Conteúdo",
      options: [
        { id: 'explicit', label: 'Filtro de Conteúdo Sensível', type: 'toggle', desc: 'Ocultar perguntas do modo Unfiltered.' },
        { id: 'language', label: 'Idioma', type: 'select', options: ['Português', 'English'], desc: 'Define a língua das perguntas.' },
      ]
    }
  ];

  return (
    <div className="min-h-screen bg-raw-onyx text-raw-bone p-8 flex flex-col items-center">
      <div className="max-w-2xl w-full pt-12">
        <div className="flex justify-between items-end mb-12">
          <h1 className="text-6xl font-archivo tracking-tighter">
            CONFIG<span className="text-raw-cyan">.</span>
          </h1>
          <button onClick={onBack} className="text-xs uppercase tracking-[0.3em] opacity-50 hover:opacity-100 transition-opacity mb-2">
            [ Voltar ]
          </button>
        </div>

        <div className="space-y-12">
          {sections.map((section) => (
            <section key={section.title}>
              <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-6 border-b border-raw-bone/10 pb-2">
                {section.title}
              </h2>
              <div className="space-y-8">
                {section.options.map((opt) => (
                  <div key={opt.id} className="flex justify-between items-start group">
                    <div className="flex-grow">
                      <h3 className="font-archivo text-xl uppercase">{opt.label}</h3>
                      <p className="text-xs opacity-40 max-w-xs mt-1 italic">{opt.desc}</p>
                    </div>
                    
                    {opt.type === 'toggle' && (
                      <button 
                        onClick={() => onUpdate(opt.id, !settings[opt.id])}
                        className={`w-12 h-6 border-2 transition-all duration-300 flex items-center px-1 ${
                          settings[opt.id] ? 'border-raw-cyan bg-raw-cyan/10' : 'border-raw-bone/20'
                        }`}
                      >
                        <div className={`w-3 h-3 transition-all duration-300 ${
                          settings[opt.id] ? 'bg-raw-cyan translate-x-6' : 'bg-raw-bone/20 translate-x-0'
                        }`} />
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </section>
          ))}
        </div>

        <div className="mt-20 pt-8 border-t border-raw-bone/5">
          <button className="w-full py-4 text-xs uppercase tracking-widest border border-raw-red text-raw-red hover:bg-raw-red hover:text-raw-bone transition-all">
            Limpar Cache e Reiniciar App
          </button>
        </div>
      </div>
    </div>
  );
};

export default Settings;
